// near-synonyms: never offer one's meaning as a wrong answer for the other
const CLOSE = { radiant: ['vivid'], vivid: ['radiant'], formidable: ['treacherous', 'sinister'], sinister: ['treacherous', 'formidable'], treacherous: ['formidable', 'sinister'] };
const vocab = (list, topic, prefix) => list.map(([w, def, eg], i) => fact(`${prefix}.${w}`, topic, `What does “${w}” mean?`, def, list.filter((x) => x[0] !== w && !(CLOSE[w] || []).includes(x[0])).filter((_, k) => (k + i) % 4 === 0).slice(0, 3).map((x) => x[1]), `${w}: ${def}. “${eg}”`, { formats: ['choice'], learn: `**${w}** means ${def}.\n_${eg}_` }));

